CREATE OR REPLACE FUNCTION ai_manifest_raw(p_case uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT jsonb_build_object('case',jsonb_build_object('id',c.id,'version',c.version,'status',c.status,'policyVersionId',c."policyVersionId"),'order',jsonb_build_object('id',o.id,'version',o.version,'status',o.status,'paymentState',o."paymentState",'amount',o."amountMinor"::text,'currency',o.currency),'capture',(SELECT jsonb_build_object('id',p.id,'version',p.version,'status',p."providerStatus",'reconciliation',p."reconciliationStatus",'gross',p."grossMinor"::text,'reserved',p."reservedMinor"::text,'refunded',p."refundedMinor"::text,'external',p."externalRefundedMinor"::text,'verifiedAt',p."verifiedAt") FROM public."Capture" p WHERE p."merchantId"=c."merchantId" AND p."orderId"=c."orderId"),'policy',(SELECT jsonb_build_object('id',v.id,'hash',v."contentHash") FROM public."PolicyVersion" v WHERE v.id=c."policyVersionId"),'evidence',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,'hash',e.sha256,'scan',e."scanStatus",'upload',e."uploadState",'cleanKey',e."cleanObjectKey",'scannedAt',e."scannedAt") ORDER BY e.id) FROM public."Evidence" e WHERE e."caseId"=c.id AND e."merchantId"=c."merchantId"),'[]'::jsonb),'comments',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',n.id,'hash',encode(sha256(convert_to(n.body,'UTF8')),'hex')) ORDER BY n.id) FROM public."CaseComment" n WHERE n."caseId"=c.id AND n.visibility='CUSTOMER'),'[]'::jsonb),'timeline',COALESCE((SELECT jsonb_agg(t.id ORDER BY t.id) FROM public."CaseTimelineEvent" t WHERE t."caseId"=c.id AND t.visibility='CUSTOMER' AND t.action NOT LIKE 'AI_%'),'[]'::jsonb)) FROM public."Case" c JOIN public."Order" o ON o.id=c."orderId" AND o."merchantId"=c."merchantId" WHERE c.id=p_case;
$$;

CREATE OR REPLACE FUNCTION ai_purge_expired() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE m uuid:=NULLIF(current_setting('app.merchant_id',true),'')::uuid;n integer;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public."AIWorkerTenant" WHERE "merchantId"=m AND "roleName"=session_user) THEN RAISE EXCEPTION 'Unauthorized AI cleanup';END IF;
 UPDATE public."AIContext" SET state='EXPIRED',"baseEncrypted"='',"requestEncrypted"=NULL,"catalogEncrypted"=NULL WHERE "merchantId"=m AND "expiresAt"<now() AND state<>'EXPIRED';GET DIAGNOSTICS n=ROW_COUNT;
 UPDATE public."Analysis" SET status='STALE' WHERE "merchantId"=m AND "contextId" IN(SELECT id FROM public."AIContext" WHERE "merchantId"=m AND state='EXPIRED');UPDATE public."Analysis" SET "outputEncrypted"=NULL WHERE "merchantId"=m AND "contextId" IN(SELECT id FROM public."AIContext" WHERE "merchantId"=m AND state='EXPIRED');
RETURN n;END$$;
